use forgedb_parser::{FieldType, RelationType, Schema};

pub fn typescript_types(schema: &Schema, version: u32) -> (String, String) {
    let mut s = String::new();
    s.push_str(&format!(
        "// Generated by ForgeDB from migrations/schemas/v{version}.forge — DO NOT EDIT.\n\
         // Rewritten on every `migrate create` and `migrate build`.\n\n"
    ));
    for e in &schema.enums {
        let variants: Vec<String> = e.variants.iter().map(|v| format!("{v:?}")).collect();
        s.push_str(&format!(
            "export type {} = {};\n",
            e.name,
            variants.join(" | ")
        ));
    }
    if !schema.enums.is_empty() {
        s.push('\n');
    }
    for st in &schema.structs {
        s.push_str(&format!("export interface {} {{\n", st.name));
        for f in &st.fields {
            s.push_str(&format!(
                "  {}: {};\n",
                f.name,
                ts_type(schema, &f.field_type)
            ));
        }
        s.push_str("}\n\n");
    }
    for m in &schema.models {
        s.push_str(&format!("export interface {} {{\n", m.name));
        for f in &m.fields {
            if !on_the_wire(&f.field_type) {
                continue;
            }
            s.push_str(&format!(
                "  {}: {};\n",
                f.name,
                ts_type(schema, &f.field_type)
            ));
        }
        s.push_str("}\n\n");
    }
    (format!("v{version}.ts"), s)
}

pub fn python_types(schema: &Schema, version: u32) -> (String, String) {
    let mut s = String::new();
    s.push_str(&format!(
        "# Generated by ForgeDB from migrations/schemas/v{version}.forge — DO NOT EDIT.\n\
         # Rewritten on every `migrate create` and `migrate build`.\n\
         from __future__ import annotations\n\n\
         from typing import Any, List, Literal, Optional, TypedDict\n\n\n"
    ));
    for e in &schema.enums {
        let variants: Vec<String> = e.variants.iter().map(|v| format!("{v:?}")).collect();
        s.push_str(&format!("{} = Literal[{}]\n", e.name, variants.join(", ")));
    }
    if !schema.enums.is_empty() {
        s.push('\n');
    }
    for st in &schema.structs {
        s.push_str(&format!("\nclass {}(TypedDict):\n", st.name));
        if st.fields.is_empty() {
            s.push_str("    pass\n");
        }
        for f in &st.fields {
            s.push_str(&format!(
                "    {}: {}\n",
                f.name,
                py_type(schema, &f.field_type)
            ));
        }
    }
    for m in &schema.models {
        s.push_str(&format!("\nclass {}(TypedDict):\n", m.name));
        let mut any = false;
        for f in &m.fields {
            if !on_the_wire(&f.field_type) {
                continue;
            }
            any = true;
            s.push_str(&format!(
                "    {}: {}\n",
                f.name,
                py_type(schema, &f.field_type)
            ));
        }
        if !any {
            s.push_str("    pass\n");
        }
    }
    (format!("v{version}.py"), s)
}

fn on_the_wire(ty: &FieldType) -> bool {
    !matches!(
        ty,
        FieldType::Relation(RelationType::OneToMany(_) | RelationType::ManyToMany(_))
            | FieldType::Component(_)
    )
}

fn ts_type(schema: &Schema, ty: &FieldType) -> String {
    match ty {
        FieldType::U32 | FieldType::U64 | FieldType::I32 | FieldType::I64 | FieldType::F64 => {
            "number".into()
        }
        FieldType::Bool => "boolean".into(),
        FieldType::String | FieldType::StringN { .. } | FieldType::Uuid => "string".into(),
        FieldType::Timestamp(_) => "string".into(),
        FieldType::Decimal => "string".into(),
        FieldType::Json => "unknown".into(),
        FieldType::Enum(name) => name.clone(),
        FieldType::StructType(name) => name.clone(),
        FieldType::OptionalStructType(name) => format!("{name} | null"),
        FieldType::Bytes(_) => "number[]".into(),
        FieldType::FixedArray(inner, _) => format!("{}[]", ts_type(schema, inner)),
        FieldType::Nullable(inner) => format!("{} | null", ts_type(schema, inner)),
        FieldType::Relation(
            RelationType::RequiredReference(_) | RelationType::OptionalReference(_),
        ) => ts_type(schema, &crate::rust::RustGenerator::resolved_type(schema, ty)),
        FieldType::Relation(RelationType::OneToMany(_) | RelationType::ManyToMany(_))
        | FieldType::Component(_) => "never".into(),
    }
}

fn py_type(schema: &Schema, ty: &FieldType) -> String {
    match ty {
        FieldType::U32 | FieldType::U64 | FieldType::I32 | FieldType::I64 => "int".into(),
        FieldType::F64 => "float".into(),
        FieldType::Bool => "bool".into(),
        FieldType::String | FieldType::StringN { .. } | FieldType::Uuid => "str".into(),
        FieldType::Timestamp(_) => "str".into(),
        FieldType::Decimal => "str".into(),
        FieldType::Json => "Any".into(),
        FieldType::Enum(name) => name.clone(),
        FieldType::StructType(name) => name.clone(),
        FieldType::OptionalStructType(name) => format!("Optional[{name}]"),
        FieldType::Bytes(_) => "List[int]".into(),
        FieldType::FixedArray(inner, _) => format!("List[{}]", py_type(schema, inner)),
        FieldType::Nullable(inner) => format!("Optional[{}]", py_type(schema, inner)),
        FieldType::Relation(
            RelationType::RequiredReference(_) | RelationType::OptionalReference(_),
        ) => py_type(schema, &crate::rust::RustGenerator::resolved_type(schema, ty)),
        FieldType::Relation(RelationType::OneToMany(_) | RelationType::ManyToMany(_))
        | FieldType::Component(_) => "Any".into(),
    }
}

pub fn typescript_host() -> (String, String) {
    ("host.ts".to_string(), TS_HOST.to_string())
}

pub fn python_host() -> (String, String) {
    ("host.py".to_string(), PY_HOST.to_string())
}

const TS_HOST: &str = r#"// Generated by ForgeDB — DO NOT EDIT. Rewritten on every migrate create/build.
import { readSync, writeSync } from "node:fs";

export type Row = Record<string, unknown>;

export function runTransform(fn: (model: string, row: Row) => Row): void {
  const buf = Buffer.alloc(1 << 16);
  let pending = "";
  for (;;) {
    let n = 0;
    try {
      n = readSync(0, buf, 0, buf.length, null);
    } catch (e) {
      const code = (e as NodeJS.ErrnoException).code;
      if (code === "EAGAIN") continue;
      if (code === "EOF") break;
      throw e;
    }
    if (n === 0) break;
    pending += buf.subarray(0, n).toString("utf8");
    for (;;) {
      const i = pending.indexOf("\n");
      if (i < 0) break;
      const line = pending.slice(0, i);
      pending = pending.slice(i + 1);
      if (line.length === 0) continue;
      const msg = JSON.parse(line) as { model: string; row: Row };
      const out = fn(msg.model, msg.row);
      writeSync(1, JSON.stringify(out) + "\n");
    }
  }
}
"#;

const PY_HOST: &str = r#"# Generated by ForgeDB — DO NOT EDIT. Rewritten on every migrate create/build.
#
# The bridge between ForgeDB's transformer and your transform. ForgeDB spawns
# this process once per migration hop and speaks one JSON object per line:
#
#   -> {"model": "Post", "row": {...}}
#   <- {...}
#
# Strictly in order, one reply per row. `readline` and an explicit flush are not
# an accident: the parent blocks on your reply, so a buffered stdout would
# deadlock the migration with no output at all.
from __future__ import annotations

import json
import sys
from typing import Any, Callable, Dict

Row = Dict[str, Any]

def run_transform(fn: Callable[[str, Row], Row]) -> None:
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        line = line.strip()
        if not line:
            continue
        msg = json.loads(line)
        out = fn(msg["model"], msg["row"])
        sys.stdout.write(json.dumps(out) + "\n")
        sys.stdout.flush()
"#;
